package solution

import "errors"

var (
	ErrInvalidCapacity = errors.New("invalid scratch capacity")
	ErrInvalidSize = errors.New("invalid allocation size")
)

type Scratch struct {
	buf         []byte
	used        int
	sharedLimit int
}

func NewScratch(capacity int, sharedLimit int) (*Scratch, error) {
	if capacity < 0 || sharedLimit < 0 || sharedLimit > capacity {
		return nil, ErrInvalidCapacity
	}
	return &Scratch{
		buf:         make([]byte, capacity),
		sharedLimit: sharedLimit,
	}, nil
}

func (s *Scratch) Take(size int) ([]byte, error) {
	if size < 0 {
		return nil, ErrInvalidSize
	}
	if size == 0 {
		return make([]byte, 0), nil
	}
	if size <= s.sharedLimit && size <= len(s.buf)-s.used {
		start := s.used
		s.used += size
		return s.buf[start:s.used], nil
	}
	return make([]byte, size), nil
}

func (s *Scratch) Reset() {
	clear(s.buf[:s.used])
	s.used = 0
}

func (s *Scratch) Used() int {
	return s.used
}
